        "rose-thorn-ghosts": {
            "title": "Rose Thorn Ghosts",
            "children": {
                "rose-thorn-ghosts": {
                    "title": "Rose & Thorn Durst (Ghost)",
                    "tipo": "json",
                    "path": "./data/rose-thorn-ghosts.json",
                    "inlineContent": "{\n  \"name\": \"Rose & Thorn Durst (Ghost)\",\n  \"source\": \"MM\",\n  \"size\": [\n    \"S\"\n  ],\n  \"type\": \"undead\",\n  \"alignment\": [\n    \"L\",\n    \"G\"\n  ],\n  \"ac\": [\n    11\n  ],\n  \"hp\": {\n    \"average\": 45,\n    \"formula\": \"10d8\"\n  },\n  \"speed\": {\n    \"walk\": 0,\n    \"fly\": 40,\n    \"canHover\": true\n  },\n  \"str\": 7,\n  \"dex\": 13,\n  \"con\": 10,\n  \"int\": 10,\n  \"wis\": 12,\n  \"cha\": 17,\n  \"resist\": [\n    \"acid\",\n    \"fire\",\n    \"lightning\",\n    \"thunder\",\n    \"bludgeoning, piercing, and slashing from nonmagical attacks\"\n  ],\n  \"immune\": [\n    \"cold\",\n    \"necrotic\",\n    \"poison\"\n  ],\n  \"conditionImmune\": [\n    \"charmed\",\n    \"exhaustion\",\n    \"frightened\",\n    \"grappled\",\n    \"paralyzed\",\n    \"petrified\",\n    \"poisoned\",\n    \"prone\",\n    \"restrained\"\n  ],\n  \"senses\": [\n    \"darkvision 60 ft.\"\n  ],\n  \"passive\": 11,\n  \"languages\": [\n    \"Common\"\n  ],\n  \"cr\": \"4\",\n  \"trait\": [\n    {\n      \"name\": \"Ethereal Sight\",\n      \"entries\": [\n        \"The ghost can see 60 feet into the Ethereal Plane when it is on the Material Plane, and vice versa.\"\n      ]\n    },\n    {\n      \"name\": \"Incorporeal Movement\",\n      \"entries\": [\n        \"The ghost can move through other creatures and objects as if they were difficult terrain. It takes 5 (1d10) force damage if it ends its turn inside an object.\"\n      ]\n    }\n  ],\n  \"action\": [\n    {\n      \"name\": \"Withering Touch\",\n      \"entries\": [\n        \"{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}17 ({@damage 4d6 + 3}) necrotic damage.\"\n      ]\n    },\n    {\n      \"name\": \"Horrifying Visage\",\n      \"entries\": [\n        \"Each non-undead creature within 60 feet of the ghost that can see it must succeed on a {@dc 13} Wisdom saving throw or be {@condition frightened} for 1 minute. If the save fails by 5 or more, the target also ages 1d4 x 10 years.\"\n      ]\n    },\n    {\n      \"name\": \"Possession {@recharge 6}\",\n      \"entries\": [\n        \"One humanoid that the ghost can see within 5 feet of it must succeed on a {@dc 15} Charisma saving throw or be possessed by the ghost; the ghost then disappears, and the target is incapacitated and loses control of its body. The ghost now controls the body but doesn't deprive the target of awareness.\"\n      ]\n    }\n  ],\n  \"fluffEntries\": [\n    \"Ficha 5etools oficial de Ghost para os espíritos das crianças no Sótão.\"\n  ],\n  \"hasToken\": true,\n  \"customToken\": \"./npc/rose_thorn_ghosts/rose_thorn_ghosts.jpg\"\n}"
                }
            }
        },
